@if(auth()->check() && auth()->user()->canManage('inventory'))
@php($expiredCount=DB::table('product_batches')->where('remaining_quantity','>',0)->where('expires_on','<',today()->toDateString())->count())
@php($soonCount=DB::table('product_batches')->where('remaining_quantity','>',0)->whereBetween('expires_on',[today()->toDateString(),today()->addDays(7)->toDateString()])->count())
@php($missingCount=DB::table('product_batches')->join('products','products.id','=','product_batches.product_id')->where('remaining_quantity','>',0)->whereNull('product_batches.expires_on')->whereIn('products.delivery_type',['dairy','fresh'])->count())
@if($expiredCount+$soonCount+$missingCount>0)<dialog id="expiry-alert" style="max-width:480px;padding:28px;border:1px solid #ddd;border-radius:16px;color:#18383e"><h2>Stock expiry alert</h2><p>{{ $expiredCount }} expired batches are blocked from sales.</p><p>{{ $soonCount }} batches expire within 7 days. Review them before dispatch.</p><p>{{ $missingCount }} older perishable batches need an expiry date. Open a batch to enter the actual details.</p><div class="actions"><a class="outline" href="{{ route('admin.batches',['expiry'=>$expiredCount?'expired':($missingCount?'missing':'soon')]) }}">Review batches</a><button type="button" id="dismiss-expiry">Dismiss</button></div></dialog><script>document.addEventListener('DOMContentLoaded',function(){var dialog=document.getElementById('expiry-alert'),key='novacart-expiry-{{ auth()->id() }}-{{ today()->toDateString() }}-{{ $expiredCount }}-{{ $soonCount }}-{{ $missingCount }}';document.getElementById('dismiss-expiry').onclick=function(){dialog.close();};try{if(!sessionStorage.getItem(key)){dialog.showModal();sessionStorage.setItem(key,'1');}}catch(e){}});</script>@endif
